package com.ezylang.evalex.parser;

import com.ezylang.evalex.config.ExpressionConfiguration;
import com.ezylang.evalex.functions.FunctionIfc;
import com.ezylang.evalex.operators.OperatorIfc;
import org.junit.Assert;
import org.junit.Test;
import org.mockito.Mockito;

import java.util.Arrays;
import java.util.Collections;
import java.util.List;

public class TokenizerTest {

    @Test
    public void tokenizerConstructorWithNullOrEmptyExpressionStringTest() {
        try {
        	new Tokenizer("", new ExpressionConfiguration());
            Assert.fail("Expected IllegalArgumentException with string empty");
        } catch (IllegalArgumentException e) {
            // Success
        }

        try {
        	new Tokenizer(null, new ExpressionConfiguration());
            Assert.fail("Expected IllegalArgumentException with string null");
        } catch (IllegalArgumentException e) {
            // Success
        }
    }

    @Test
    public void tokenizerConstructorWithExpressionStringTest() {
    	ExpressionConfiguration configuration = new ExpressionConfiguration();
        Tokenizer tokenizer = new Tokenizer("1 + 1", configuration);
        Assert.assertNotNull(tokenizer);
    }

    @Test
    public void parseFunctionIfcFromStringTest() throws ParseException {
    	FunctionIfc functionIfc = Mockito.mock(FunctionIfc.class);
        Mockito.when(functionIfc.apply(Mockito.any())).thenReturn(2.0);
        Tokenizer tokenizer = new Tokenizer("2 + 2", functionIfc);
        Assert.assertEquals(Arrays.asList(new Token(2), new Token("+"), new Token(2)), tokenizer.parse());
    }

    @Test
    public void parseOperatorIfcFromStringTest() throws ParseException {
        OperatorIfc operatorIfc = Mockito.mock(OperatorIfc.class);
        Mockito.when(operatorIfc.apply(Mockito.any(), Mockito.any())).thenReturn(2.0);
        Tokenizer tokenizer = new Tokenizer("2 * 2", operatorIfc);
        Assert.assertEquals(Arrays.asList(new Token(2), new Token("*"), new Token(2)), tokenizer.parse());
    }

    @Test
    public void parseStringLiteralEmptyStringTest() throws ParseException {
        Tokenizer tokenizer = new Tokenizer("\"\"", new ExpressionConfiguration());
        Assert.assertEquals(Collections.singletonList(new Token(TokenType.STRING_LITERAL)), tokenizer.parse());
    }

    @Test
    public void parseStringLiteralTest() throws ParseException {
        Tokenizer tokenizer = new Tokenizer("\"Test\"", new ExpressionConfiguration());
        Assert.assertEquals(Collections.singletonList(new Token("Test")), tokenizer.parse());
    }

    @Test
    public void parseStringLiteralFailedTest() {
        try {
            Tokenizer tokenizer = new Tokenizer("\"Test", new ExpressionConfiguration());
            tokenizer.parse();
            Assert.fail("Expected ParseException");
        } catch (ParseException e) {
            // Expected
        }
    }
}
